steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -d '{
    "query": "{
      issue(identifier: \"WEB-5\") {
        id
        identifier
        title
        comments(first: 50) {
          edges {
            node {
              id
              body
              resolvedAt
              user {
                id
                name
              }
            }
          }
        }
      }
    }'
